/* eslint-disable space-in-parens */

import Complex128Array = require( '@stdlib/array/complex128' );
import Complex64Array = require( '@stdlib/array/complex64' );
import BooleanArray = require( '@stdlib/array/bool' );
import Complex128 = require( '@stdlib/complex/float64/ctor' );
import toAccessorArray = require( '@stdlib/array/base/to-accessor-array' );
import toFilledBy = require( './index' );

/**
* Callback function.
*
* @param value - current array element
* @returns fill value
*/
function fcn<T>( value: T ): T {
	return value;
}

/**
* Callback function returning a number.
*
* @returns fill value
*/
function clbk(): number {
	return 5;
}

/**
* Callback function returning a complex number.
*
* @returns fill value
*/
function complexClbk(): Complex128 {
	return new Complex128( 5.0, 5.0 );
}


// TESTS //

// The function returns an updated array...
{
	toFilledBy( [ 1, 2, 3, 4 ], 1, 3, fcn ); // $ExpectType number[]
	toFilledBy( new Float64Array( [ 1, 2, 3, 4 ] ), 1, 3, fcn ); // $ExpectType Float64Array
	toFilledBy( new Float32Array( [ 1, 2, 3, 4 ] ), 1, 3, fcn ); // $ExpectType Float32Array
	toFilledBy( new Int32Array( [ 1, 2, 3, 4 ] ), 1, 3, fcn ); // $ExpectType Int32Array
	toFilledBy( new Int16Array( [ 1, 2, 3, 4 ] ), 1, 3, fcn ); // $ExpectType Int16Array
	toFilledBy( new Int8Array( [ 1, 2, 3, 4 ] ), 1, 3, fcn ); // $ExpectType Int8Array
	toFilledBy( new Uint32Array( [ 1, 2, 3, 4 ] ), 1, 3, fcn ); // $ExpectType Uint32Array
	toFilledBy( new Uint16Array( [ 1, 2, 3, 4 ] ), 1, 3, fcn ); // $ExpectType Uint16Array
	toFilledBy( new Uint8Array( [ 1, 2, 3, 4 ] ), 1, 3, fcn ); // $ExpectType Uint8Array
	toFilledBy( new Uint8ClampedArray( [ 1, 2, 3, 4 ] ), 1, 3, fcn ); // $ExpectType Uint8ClampedArray
	toFilledBy( new Complex128Array( 5 ), 0, 1, fcn ); // $ExpectType Complex128Array
	toFilledBy( new Complex64Array( 5 ), 0, 1, fcn ); // $ExpectType Complex64Array
	toFilledBy( new BooleanArray( [ true, false, true, false ] ), 0, 3, fcn ); // $ExpectType BooleanArray
	toFilledBy<number, number>( toAccessorArray( [ 1, 2, 3, 4 ] ), 1, 3, fcn ); // $ExpectType number[]

	toFilledBy( [ 1, 2, 3, 4 ], 1, 3, fcn, {} ); // $ExpectType number[]
	toFilledBy( new Float64Array( [ 1, 2, 3, 4 ] ), 1, 3, fcn, {} ); // $ExpectType Float64Array
	toFilledBy( new Complex128Array( 5 ), 0, 1, fcn, {} ); // $ExpectType Complex128Array
	toFilledBy( new BooleanArray( [ true, false, true, false ] ), 0, 3, fcn, {} ); // $ExpectType BooleanArray
}

// The compiler throws an error if the function is provided a first argument which is not a collection...
{
	toFilledBy( 5, 1, 3, fcn ); // $ExpectError
	toFilledBy( true, 1, 3, fcn ); // $ExpectError
	toFilledBy( false, 1, 3, fcn ); // $ExpectError
	toFilledBy( null, 1, 3, fcn ); // $ExpectError
	toFilledBy( void 0, 1, 3, fcn ); // $ExpectError
	toFilledBy( {}, 1, 3, fcn ); // $ExpectError
	toFilledBy( ( x: number ): number => x, 1, 3, fcn ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	const x = [ 1, 2, 3, 4 ];

	toFilledBy( x, 'abc', 3, fcn ); // $ExpectError
	toFilledBy( x, true, 3, fcn ); // $ExpectError
	toFilledBy( x, false, 3, fcn ); // $ExpectError
	toFilledBy( x, null, 3, fcn ); // $ExpectError
	toFilledBy( x, void 0, 3, fcn ); // $ExpectError
	toFilledBy( x, [ '1' ], 3, fcn ); // $ExpectError
	toFilledBy( x, {}, 3, fcn ); // $ExpectError
	toFilledBy( x, ( x: number ): number => x, 3, fcn ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
{
	const x = [ 1, 2, 3, 4 ];

	toFilledBy( x, 1, 'abc', fcn ); // $ExpectError
	toFilledBy( x, 1, true, fcn ); // $ExpectError
	toFilledBy( x, 1, false, fcn ); // $ExpectError
	toFilledBy( x, 1, null, fcn ); // $ExpectError
	toFilledBy( x, 1, void 0, fcn ); // $ExpectError
	toFilledBy( x, 1, [ '1' ], fcn ); // $ExpectError
	toFilledBy( x, 1, {}, fcn ); // $ExpectError
	toFilledBy( x, 1, ( x: number ): number => x, fcn ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a function...
{
	const x = [ 1, 2, 3, 4 ];

	toFilledBy( x, 1, 3, 'abc' ); // $ExpectError
	toFilledBy( x, 1, 3, 5 ); // $ExpectError
	toFilledBy( x, 1, 3, true ); // $ExpectError
	toFilledBy( x, 1, 3, false ); // $ExpectError
	toFilledBy( x, 1, 3, null ); // $ExpectError
	toFilledBy( x, 1, 3, void 0 ); // $ExpectError
	toFilledBy( x, 1, 3, [] ); // $ExpectError
	toFilledBy( x, 1, 3, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = [ 1, 2, 3, 4 ];

	toFilledBy(); // $ExpectError
	toFilledBy( x ); // $ExpectError
	toFilledBy( x, 1 ); // $ExpectError
	toFilledBy( x, 1, 3 ); // $ExpectError
}

// Attached to the main export is an `assign` method which returns a collection...
{
	const x = [ 1, 2, 3, 4 ];
	const y = new Complex128Array( 4 );

	toFilledBy.assign( x, 1, 3, clbk, [ 0, 0, 0, 0 ], 1, 0 ); // $ExpectType number[]
	toFilledBy.assign( x, 1, 3, clbk, new Float64Array( 4 ), 1, 0 ); // $ExpectType Float64Array
	toFilledBy.assign( x, 1, 3, clbk, new Float32Array( 4 ), 1, 0 ); // $ExpectType Float32Array
	toFilledBy.assign( x, 1, 3, clbk, new Int32Array( 4 ), 1, 0 ); // $ExpectType Int32Array
	toFilledBy.assign( x, 1, 3, clbk, new Int16Array( 4 ), 1, 0 ); // $ExpectType Int16Array
	toFilledBy.assign( x, 1, 3, clbk, new Int8Array( 4 ), 1, 0 ); // $ExpectType Int8Array
	toFilledBy.assign( x, 1, 3, clbk, new Uint32Array( 4 ), 1, 0 ); // $ExpectType Uint32Array
	toFilledBy.assign( x, 1, 3, clbk, new Uint16Array( 4 ), 1, 0 ); // $ExpectType Uint16Array
	toFilledBy.assign( x, 1, 3, clbk, new Uint8Array( 4 ), 1, 0 ); // $ExpectType Uint8Array
	toFilledBy.assign( x, 1, 3, clbk, new Uint8ClampedArray( 4 ), 1, 0 ); // $ExpectType Uint8ClampedArray
	toFilledBy.assign( y, 0, 1, complexClbk, new Complex128Array( 4 ), 1, 0 ); // $ExpectType Complex128Array
	toFilledBy.assign( y, 0, 1, complexClbk, new Complex64Array( 4 ), 1, 0 ); // $ExpectType Complex64Array
}

// The compiler throws an error if the `assign` method is provided a first argument which is not an array-like object...
{
	const out = [ 0, 0, 0, 0 ];

	toFilledBy.assign( 1, 1, 3, fcn, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( true, 1, 3, fcn, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( false, 1, 3, fcn, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( null, 1, 3, fcn, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( void 0, 1, 3, fcn, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( {}, 1, 3, fcn, out, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `assign` method is provided a second argument which is not a number...
{
	const x = [ 1, 2, 3, 4 ];
	const out = [ 0, 0, 0, 0 ];

	toFilledBy.assign( x, '1', 3, fcn, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, true, 3, fcn, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, false, 3, fcn, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, null, 3, fcn, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, void 0, 3, fcn, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, [], 3, fcn, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, {}, 3, fcn, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, ( x: number ): number => x, 3, fcn, out, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `assign` method is provided a third argument which is not a number...
{
	const x = [ 1, 2, 3, 4 ];
	const out = [ 0, 0, 0, 0 ];

	toFilledBy.assign( x, 1, '1', fcn, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, true, fcn, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, false, fcn, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, null, fcn, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, void 0, fcn, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, [], fcn, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, {}, fcn, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, ( x: number ): number => x, fcn, out, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `assign` method is provided a fourth argument which is not a function...
{
	const x = [ 1, 2, 3, 4 ];
	const out = [ 0, 0, 0, 0 ];

	toFilledBy.assign( x, 1, 3, '1', out, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, 3, 5, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, 3, true, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, 3, false, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, 3, null, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, 3, void 0, out, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, 3, [], out, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, 3, {}, out, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `assign` method is provided a fifth argument which is not an array-like object...
{
	const x = [ 1, 2, 3, 4 ];

	toFilledBy.assign( x, 1, 3, fcn, 1, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn, true, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn, false, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn, null, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn, void 0, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn, {}, 1, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn, ( x: number ): number => x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `assign` method is provided a sixth argument which is not a number...
{
	const x = [ 1, 2, 3, 4 ];
	const out = [ 0, 0, 0, 0 ];

	toFilledBy.assign( x, 1, 3, fcn, out, '1', 0 ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn, out, true, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn, out, false, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn, out, null, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn, out, void 0, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn, out, [], 0 ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn, out, {}, 0 ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn, out, ( x: number ): number => x, 0 ); // $ExpectError
}

// The compiler throws an error if the `assign` method is provided a seventh argument which is not a number...
{
	const x = [ 1, 2, 3, 4 ];
	const out = [ 0, 0, 0, 0 ];

	toFilledBy.assign( x, 1, 3, fcn, out, 1, '1' ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn, out, 1, true ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn, out, 1, false ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn, out, 1, null ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn, out, 1, void 0 ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn, out, 1, [] ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn, out, 1, {} ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn, out, 1, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the `assign` method is provided an unsupported number of arguments...
{
	const x = [ 1, 2, 3, 4 ];
	const out = [ 0, 0, 0, 0 ];

	toFilledBy.assign(); // $ExpectError
	toFilledBy.assign( x ); // $ExpectError
	toFilledBy.assign( x, 1 ); // $ExpectError
	toFilledBy.assign( x, 1, 3 ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn, out ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn, out, 1 ); // $ExpectError
	toFilledBy.assign( x, 1, 3, fcn, out, 1, 0, {}, 1 ); // $ExpectError
}
